{
  "plan_version": "1.0",
  "objective": "Determine the optimal marketing messaging for the Trail Shell Jacket by analyzing product attributes, customer review sentiment, key praised benefits, and frequent customer objections.",
  "success_criteria": [
    "Identify the exact product specifications and pricing for the Trail Shell Jacket.",
    "Quantify customer sentiment, average rating, positive themes, and negative feedback/objections from deduplicated customer reviews.",
    "Formulate a structured messaging recommendation (headline, primary benefit, objection handling, and proof points) grounded in customer voice and brand guidelines."
  ],
  "execution_limits": {
    "max_plan_steps": 3,
    "max_tool_calls": 8,
    "max_sql_calls": 5,
    "max_replans": 1,
    "max_llm_calls": 6
  },
  "steps": [
    {
      "id": "step_1",
      "objective": "Identify Trail Shell Jacket product details",
      "purpose": "Retrieve product_id, category, list price, launch date, and exact naming to anchor messaging in true product attributes.",
      "tool_candidates": ["run_sql"],
      "inputs": {
        "query": "SELECT product_id, product_name, category, list_price, unit_cost, launch_date FROM public.products WHERE product_name ILIKE '%Trail Shell Jacket%';"
      },
      "depends_on": [],
      "output_key": "product_details",
      "guide_ids": ["KB1", "KB6"],
      "status": "pending",
      "optional": false,
      "skip_if_data_unavailable": false
    },
    {
      "id": "step_2",
      "objective": "Analyze customer reviews and feedback themes",
      "purpose": "Analyze rating distribution and extract prominent customer language, praised features/benefits, and critical objections or complaints from deduplicated reviews.",
      "tool_candidates": ["run_sql"],
      "inputs": {
        "query": "SELECT r.rating, r.review_title, r.review_text FROM (SELECT DISTINCT review_id, product_id, rating, review_title, review_text FROM public.reviews) r JOIN public.products p ON r.product_id = p.product_id WHERE p.product_name ILIKE '%Trail Shell Jacket%';"
      },
      "depends_on": [
        {
          "step_id": "step_1",
          "output_key": "product_details",
          "optional": false
        }
      ],
      "output_key": "review_insights",
      "guide_ids": ["KB3", "KB5"],
      "status": "pending",
      "optional": false,
      "skip_if_data_unavailable": false
    },
    {
      "id": "step_3",
      "objective": "Examine return and fulfillment dynamics for the product",
      "purpose": "Check return rates or delivery metrics to see if product returns reinforce any specific objections found in reviews.",
      "tool_candidates": ["run_sql"],
      "inputs": {
        "query": "SELECT o.status, COUNT(DISTINCT o.order_id) AS order_count, SUM(oi.quantity) AS total_units FROM public.orders o JOIN public.order_items oi ON o.order_id = oi.order_id JOIN public.products p ON oi.product_id = p.product_id JOIN public.customers c ON o.customer_id = c.customer_id WHERE p.product_name ILIKE '%Trail Shell Jacket%' AND c.is_internal = false GROUP BY o.status;"
      },
      "depends_on": [
        {
          "step_id": "step_1",
          "output_key": "product_details",
          "optional": false
        }
      ],
      "output_key": "order_performance",
      "guide_ids": ["KB3", "KB6", "KB8"],
      "status": "pending",
      "optional": true,
      "skip_if_data_unavailable": true
    }
  ]
}

